export function normalizeLocale(value: string): Locale {
  const locale = value.toLowerCase();
  if (/^zh-(tw|hk|hant)/.test(locale)) return 'zh-TW';
  if (locale.startsWith('zh')) return 'zh-CN';
  if (locale.startsWith('pt')) return 'pt-BR';
  return supportedLocales.find(({ id }) => locale === id.toLowerCase() || locale.startsWith(`${id.toLowerCase()}-`))?.id || 'en';
}
export function detectLocale(): Locale { return normalizeLocale(navigator.language); }
