export function createTranslator(locale: Locale) {
  return (key: MessageKey): string => key in aiProTranslations.en
    ? aiProTranslations[locale][key as AiProKey]
    : key in proTabIntelligenceTranslations.en
    ? proTabIntelligenceTranslations[locale][key as ProTabIntelligenceKey]
    : key in billingUiTranslations.en
    ? billingUiTranslations[locale][key as BillingUiKey]
    : key in tabOrganizerTranslations.en
    ? tabOrganizerTranslations[locale][key as TabOrganizerKey]
    : key in websiteNavigationTranslations[locale]
    ? websiteNavigationTranslations[locale][key as WebsiteNavigationKey]
    : key in growthUiTranslations[locale]
    ? growthUiTranslations[locale][key as GrowthUiKey]
    : key in authModalTranslations[locale]
    ? authModalTranslations[locale][key as AuthModalKey]
    : key in accountTranslations[locale]
    ? accountTranslations[locale][key as AccountKey]
    : key in entitlementUiTranslations[locale]
    ? entitlementUiTranslations[locale][key as EntitlementUiKey]
    : key in proGateTranslations[locale]
    ? proGateTranslations[locale][key as ProGateKey]
    : key in wastebasketDeleteTranslations[locale]
    ? wastebasketDeleteTranslations[locale][key as WastebasketDeleteKey]
    : key in backupTranslations[locale]
    ? backupTranslations[locale][key as BackupKey]
    : key in feedbackTranslations[locale]
    ? feedbackTranslations[locale][key as FeedbackKey]
    : key in incognitoGuideTranslations[locale]
    ? incognitoGuideTranslations[locale][key as IncognitoGuideKey]
    : key in privateSetupTranslations[locale]
    ? privateSetupTranslations[locale][key as PrivateSetupKey]
    : key in privateModeTranslations[locale]
    ? privateModeTranslations[locale][key as PrivateModeKey]
    : key in vaultSecurityTranslations[locale]
    ? vaultSecurityTranslations[locale][key as VaultSecurityKey]
    : key in archiveUiTranslations[locale]
    ? archiveUiTranslations[locale][key as ArchiveUiKey]
    : key in siteSearchTranslations[locale]
    ? siteSearchTranslations[locale][key as SiteSearchKey]
    : key in tagManagerTranslations[locale]
    ? tagManagerTranslations[locale][key as TagManagerKey]
    : key in tagUiTranslations[locale]
    ? tagUiTranslations[locale][key as TagUiKey]
    : key in paginationTranslations[locale]
    ? paginationTranslations[locale][key as PaginationKey]
    : key === 'clearSearch'
    ? clearSearchTranslations[locale]
    : key in safeDeleteTranslations[locale]
    ? safeDeleteTranslations[locale][key as SafeDeleteKey]
    : key in timelineFilterTranslations[locale]
    ? timelineFilterTranslations[locale][key as TimelineFilterKey]
    : key in historyActionTranslations[locale]
    ? historyActionTranslations[locale][key as HistoryActionKey]
    : key in systemMessages[locale]
      ? systemMessages[locale][key as SystemMessageKey]
      : key in baseCompletionTranslations[locale]
      ? baseCompletionTranslations[locale][key] || (en as Record<string, string>)[key] || key
      : translations[locale][key] || (en as Record<string, string>)[key] || key;
}
